def is_valid(value: str) -> bool:
    compact = value.replace(' ', '')
    if len(compact) < 2 or not compact.isdigit():
        return False
    total = 0
    for index, char in enumerate(reversed(compact)):
        digit = int(char)
        if index % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    return total % 10 == 0

def annotate(board: list[str]) -> list[str]:
    if not board:
        return []
    width = len(board[0])
    if any(len(row) != width for row in board):
        raise ValueError('board must be rectangular')
    if any(char not in {' ', '*'} for row in board for char in row):
        raise ValueError('board contains an invalid character')
    result = []
    for row_index, row in enumerate(board):
        output = []
        for column_index, char in enumerate(row):
            if char == '*':
                output.append('*')
                continue
            count = 0
            for row_delta in (-1, 0, 1):
                for column_delta in (-1, 0, 1):
                    if row_delta == column_delta == 0:
                        continue
                    neighbor_row = row_index + row_delta
                    neighbor_column = column_index + column_delta
                    if 0 <= neighbor_row < len(board) and 0 <= neighbor_column < width and board[neighbor_row][neighbor_column] == '*':
                        count += 1
            output.append(str(count) if count else ' ')
        result.append(''.join(output))
    return result

def matrix_views(text: str) -> dict[str, list[list[int]]]:
    if not text or any(not line.strip() for line in text.splitlines()):
        raise ValueError('matrix rows are required')
    try:
        rows = [[int(value) for value in line.split()] for line in text.splitlines()]
    except ValueError as error:
        raise ValueError('matrix must contain integers') from error
    width = len(rows[0])
    if width == 0 or any(len(row) != width for row in rows):
        raise ValueError('matrix must be rectangular')
    return {'rows': rows, 'columns': [list(column) for column in zip(*rows)]}

def count_words(sentence: str) -> dict[str, int]:
    counts = {}
    token = []
    def flush():
        word = ''.join(token).strip("'").lower()
        token.clear()
        if word:
            counts[word] = counts.get(word, 0) + 1
    for char in sentence:
        if char.isalnum() or char == "'":
            token.append(char)
        else:
            flush()
    flush()
    return counts

def run_length(operation: str, text: str) -> str:
    if operation == 'encode':
        if not text:
            return ''
        result = []
        start = 0
        for index in range(1, len(text) + 1):
            if index == len(text) or text[index] != text[start]:
                count = index - start
                result.append((str(count) if count > 1 else '') + text[start])
                start = index
        return ''.join(result)
    if operation == 'decode':
        result, digits = [], []
        for char in text:
            if char.isdigit():
                digits.append(char)
            else:
                result.append(char * (int(''.join(digits)) if digits else 1))
                digits.clear()
        return ''.join(result)
    raise ValueError('operation must be encode or decode')

def diagonal_difference(matrix: list[list[int]]) -> int:
    if not matrix or any(len(row) != len(matrix) for row in matrix):
        raise ValueError('matrix must be non-empty and square')
    size = len(matrix)
    primary = sum(matrix[index][index] for index in range(size))
    secondary = sum(matrix[index][size - 1 - index] for index in range(size))
    return abs(primary - secondary)

def to_24_hour(value: str) -> str:
    if len(value) != 10 or value[2] != ':' or value[5] != ':' or value[8:] not in {'AM', 'PM'}:
        raise ValueError('invalid time format')
    parts = value[:8].split(':')
    if any(len(part) != 2 or not part.isdigit() for part in parts):
        raise ValueError('invalid time format')
    hour, minute, second = map(int, parts)
    if not 1 <= hour <= 12 or not 0 <= minute < 60 or not 0 <= second < 60:
        raise ValueError('time component out of range')
    if value[8:] == 'AM':
        hour = 0 if hour == 12 else hour
    elif hour != 12:
        hour += 12
    return f'{hour:02d}:{minute:02d}:{second:02d}'

def caesar_cipher(text: str, shift: int) -> str:
    if shift < 0:
        raise ValueError('shift must be non-negative')
    shift %= 26
    output = []
    for char in text:
        if 'a' <= char <= 'z':
            output.append(chr((ord(char) - ord('a') + shift) % 26 + ord('a')))
        elif 'A' <= char <= 'Z':
            output.append(chr((ord(char) - ord('A') + shift) % 26 + ord('A')))
        else:
            output.append(char)
    return ''.join(output)

def is_pangram(sentence: str) -> bool:
    letters = {char.lower() for char in sentence if char.isascii() and char.isalpha()}
    return len(letters) == 26

def mini_max_sum(values: list[int]) -> tuple[int, int]:
    if len(values) != 5 or any(not isinstance(value, int) for value in values):
        raise ValueError('exactly five integers are required')
    total = sum(values)
    return total - max(values), total - min(values)

def two_sum(values: list[int], target: int) -> list[int]:
    seen = {}
    for index, value in enumerate(values):
        complement = target - value
        if complement in seen:
            return [seen[complement], index]
        seen[value] = index
    raise ValueError('no pair found')

def valid_parentheses(text: str) -> bool:
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for char in text:
        if char in '([{':
            stack.append(char)
        elif char in pairs:
            if not stack or stack.pop() != pairs[char]:
                return False
        else:
            raise ValueError('unsupported character')
    return not stack

def max_profit(prices: list[int]) -> int:
    minimum = None
    best = 0
    for price in prices:
        if minimum is None or price < minimum:
            minimum = price
        else:
            best = max(best, price - minimum)
    return best

def binary_search(values: list[int], target: int) -> int:
    low, high = 0, len(values) - 1
    while low <= high:
        middle = (low + high) // 2
        if values[middle] == target:
            return middle
        if values[middle] < target:
            low = middle + 1
        else:
            high = middle - 1
    return -1

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if any(len(item) != 2 or item[0] > item[1] for item in intervals):
        raise ValueError('invalid interval')
    ordered = sorted((item[0], item[1]) for item in intervals)
    merged = []
    for start, end in ordered:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    return merged

def sum_multiples(limit: int, divisors=(3, 5)) -> int:
    unique = tuple(dict.fromkeys(divisors))
    if any(value <= 0 for value in unique):
        raise ValueError('divisors must be positive')
    if limit <= 0:
        return 0
    if len(unique) != 2:
        return sum(value for value in range(limit) if any(value % divisor == 0 for divisor in unique))
    left, right = unique
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a
    def series(divisor):
        count = (limit - 1) // divisor
        return divisor * count * (count + 1) // 2
    common = left * right // gcd(left, right)
    return series(left) + series(right) - series(common)

def even_fibonacci_sum(limit: int) -> int:
    first, second = 1, 2
    total = 0
    while second < limit:
        if second % 2 == 0:
            total += second
        first, second = second, first + second
    return total

def largest_prime_factor(value: int) -> int:
    if value <= 1:
        raise ValueError('value must exceed one')
    largest = 1
    factor = 2
    while factor * factor <= value:
        while value % factor == 0:
            largest = factor
            value //= factor
        factor = 3 if factor == 2 else factor + 2
    return max(largest, value)

def largest_palindrome_product(digits: int) -> int:
    if digits not in {1, 2, 3}:
        raise ValueError('digits must be between one and three')
    lower, upper = 10 ** (digits - 1), 10 ** digits - 1
    best = 0
    for left in range(upper, lower - 1, -1):
        if left * upper <= best:
            break
        for right in range(left, lower - 1, -1):
            product = left * right
            if product <= best:
                break
            text = str(product)
            if text == text[::-1]:
                best = product
                break
    return best

def smallest_multiple(maximum: int) -> int:
    if not isinstance(maximum, int) or not 1 <= maximum <= 50:
        raise ValueError('maximum must be an integer from one through fifty')
    def gcd(left, right):
        while right:
            left, right = right, left % right
        return left
    result = 1
    for value in range(2, maximum + 1):
        result = result * value // gcd(result, value)
    return result

def make_readable(seconds: int) -> str:
    if isinstance(seconds, bool) or not isinstance(seconds, int) or not 0 <= seconds <= 359999:
        raise ValueError('seconds out of range')
    hours, remainder = divmod(seconds, 3600)
    minutes, seconds = divmod(remainder, 60)
    return f'{hours:02d}:{minutes:02d}:{seconds:02d}'

def format_duration(seconds: int) -> str:
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds < 0:
        raise ValueError('seconds must be a non-negative integer')
    if seconds == 0:
        return 'now'
    units = [('year', 31536000), ('day', 86400), ('hour', 3600), ('minute', 60), ('second', 1)]
    parts = []
    for name, size in units:
        count, seconds = divmod(seconds, size)
        if count:
            parts.append(f"{count} {name}{'' if count == 1 else 's'}")
    if len(parts) == 1:
        return parts[0]
    return ', '.join(parts[:-1]) + ' and ' + parts[-1]

def digital_root(value: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValueError('value must be a non-negative integer')
    return 0 if value == 0 else 1 + (value - 1) % 9

def count_bits(value: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValueError('value must be a non-negative integer')
    count = 0
    while value:
        value &= value - 1
        count += 1
    return count

def duplicate_encode(text: str) -> str:
    normalized = text.casefold()
    counts = {}
    for char in normalized:
        counts[char] = counts.get(char, 0) + 1
    return ''.join('(' if counts[char] == 1 else ')' for char in normalized)

def fizzbuzz(first: int, second: int, maximum: int) -> list[str]:
    if any(isinstance(value, bool) or not isinstance(value, int) or value <= 0 for value in (first, second, maximum)):
        raise ValueError('arguments must be positive integers')
    result = []
    for value in range(1, maximum + 1):
        if value % first == 0 and value % second == 0:
            result.append('FizzBuzz')
        elif value % first == 0:
            result.append('Fizz')
        elif value % second == 0:
            result.append('Buzz')
        else:
            result.append(str(value))
    return result

def absolute_difference(left: int, right: int) -> int:
    if any(isinstance(value, bool) or not isinstance(value, int) for value in (left, right)):
        raise ValueError('integer arguments are required')
    return abs(left - right)

def sum_encoded_powers(values: list[int]) -> int:
    total = 0
    for value in values:
        if isinstance(value, bool) or not isinstance(value, int) or value < 10:
            raise ValueError('each encoding must contain a base and exponent')
        base, exponent = divmod(value, 10)
        total += base ** exponent
    return total

def count_below_zero(temperatures: list[int]) -> int:
    if any(isinstance(value, bool) or not isinstance(value, int) for value in temperatures):
        raise ValueError('temperatures must be integers')
    return sum(value < 0 for value in temperatures)

def hyphen_acronym(name: str) -> str:
    parts = name.split('-')
    if len(parts) < 2 or any(not part or not part.isascii() or not part.isalpha() for part in parts):
        raise ValueError('invalid hyphenated name')
    return ''.join(part[0].upper() for part in parts)
